import { Mesh, PlaneGeometry, Group, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();

  // Plane geometry based on atlas region aspect ratio (512x320 => 1.6)
  const planeWidth = 1.6;
  const planeHeight = 1;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);

  // Basic node material with a placeholder texture node
  const material = new MeshBasicNodeMaterial();
  material.set('map', texture(null, uv()));
  material.needsUpdate = true;

  const mesh = new Mesh(geometry, material);
  // Billboard toward camera each frame
  mesh.onBeforeRender = (_, __, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };
  root.add(mesh);

  // Load texture asynchronously (function stays synchronous)
  let loadedTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTex = tex;
      material.set('map', texture(tex, uv()));
      material.needsUpdate = true;
    });
  }

  // Render text items via fontAtlas
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 39,
      color: (config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2'),
      align: 'left',
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    // Center text on the plane, slightly in front
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // Apply cinematic primitives if any
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handler = ctx.primitives[prim.name](root, prim.params);
      primitiveHandles.push(handler);
    }
  }

  // User data for cleanup and handlers
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    // Dispose loaded texture
    if (loadedTex) loadedTex.dispose();
    // Cleanup primitives
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
    // Kill any GSAP timelines (none in this node, but safe)
    gsap.globalTimeline.clear();
  };

  return root;
}
